#include <bits/stdc++.h>
using namespace std;

int main() {
    auto start = chrono::steady_clock::now();
    long long s = 0;
    for (int i = 0; i < 100000000; i++) s += i % 7;
    auto end = chrono::steady_clock::now();
    double ms = chrono::duration<double, milli>(end - start).count();
    cout << s << '\n';
    cerr << "czas: " << ms << " ms\n";   // na cerr, żeby nie psuć wyniku
}

